action.command:
cat > /tmp/srv.mjs <<'EOF'
import http from 'http';
import fs from 'fs';
import path from 'path';
const root = '/workspace/build';
const types = {'.html':'text/html','.js':'application/javascript','.css':'text/css','.json':'application/json','.png':'image/png','.ico':'image/x-icon','.svg':'image/svg+xml','.txt':'text/plain','.woff2':'font/woff2'};
http.createServer((req,res)=>{
  let p = decodeURIComponent(req.url.split('?')[0]);
  let f = path.join(root,p);
  try{ if(fs.statSync(f).isDirectory()) f=path.join(f,'index.html'); }catch(e){ f=path.join(root,p,'index.html'); }
  fs.readFile(f,(e,d)=>{
    if(e){ res.writeHead(404); res.end('nf'); return; }
    res.writeHead(200,{'Content-Type':types[path.extname(f)]||'application/octet-stream'});
    res.end(d);
  });
}).listen(8099,()=>console.log('listening'));
EOF
node /tmp/srv.mjs >/tmp/http.log 2>&1 &
sleep 2
cat /tmp/http.log
for p in "/" "/de/" "/en/" "/de/resources/" "/en/resources/joinup/" "/fit-standards/" "/search-data/search-en.json" "/_next/static/chunks/main-6936ae913717855c.js" "/robots.txt"; do
  code=$(curl -s -o /dev/null -w "%{http_code}" "http://localhost:8099$p")
  echo "$code  $p"
done

